'use strict';

// Independent published numbers, NOT baselines generated by the module.
// Run: node tests/seawater-density-reference-20261117.cjs
// Node built-ins only: no jsdom, GSW package, network or NODE_PATH required.
// Valid domain: SP 0..40, ITS-90 in-situ t 0..40 C, sea p 0..9989.8675 dbar.
// Numerical tolerances below are implementation/printed-digit tolerances,
// not experimental uncertainty or a bound on the ignored SA anomaly.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const source = fs.readFileSync(path.join(__dirname, '..', 'seawater-density-20261117.js'), 'utf8');
const context = vm.createContext({ window: {} });
vm.runInContext(source, context, { filename: 'seawater-density-20261117.js' });
const { density, validRange } = context.window.MT_SEAWATER;
const RealmRangeError = vm.runInContext('RangeError', context);
const counts = { published: 0, practical: 0, working: 0, refusals: 0, monotonic: 0, contract: 0 };
function near(group, actual, expected, tolerance, label) {
  assert(Number.isFinite(actual), label + ': result must be finite');
  assert(Math.abs(actual - expected) <= tolerance,
    `${label}: ${actual} differs from ${expected} by ${actual - expected}; tolerance ${tolerance}`);
  counts[group]++;
}
function check(group, condition, label) {
  assert(condition, label);
  counts[group]++;
}
function refuses(args, code, field) {
  assert.throws(() => density(...args), error =>
    error instanceof RealmRangeError && error.code === code && error.field === field,
  `${code}, field=${field}`);
  counts.refusals++;
}

// GSW official documentation, gsw_rho_t_exact, example (six literal densities):
// https://www.teos-10.org/pubs/gsw/html/gsw_rho_t_exact.html
// Example inputs are SA in g/kg, not SP. Convert those *input* values by the
// published SR definition so the API assumption SA=SR reproduces each state.
// Output references remain literal published numbers. The independent GSW
// SR_from_SP examples below separately anchor the scale conversion.
// Tolerance 2e-9 kg/m3 allows binary64 summation differences; physical/model
// uncertainty is much larger. These are Gibbs checks, NOT 75-term checks.
const gswDensityCases = [
  [34.7118, 28.7856, 10, 1021.840173185531],
  [34.8915, 28.4329, 50, 1022.262689926782],
  [35.0256, 22.8103, 125, 1024.427715941676],
  [34.8472, 10.2600, 250, 1027.790201811623],
  [34.7366, 6.8863, 600, 1029.837714725961],
  [34.7324, 4.4036, 1000, 1032.002404116447]
];
let maxGswError = 0;
for (const [sa, t, p, rho] of gswDensityCases) {
  const result = density(sa * 35 / 35.16504, t, p);
  near('published', result.rho, rho, 2e-9, `GSW rho_t_exact SA=${sa}, t=${t}, p=${p}`);
  maxGswError = Math.max(maxGswError, Math.abs(result.rho - rho));
}

// GSW official gsw_SR_from_SP example; absolute tolerance 2e-13 g/kg.
// https://www.teos-10.org/pubs/gsw/html/gsw_SR_from_SP.html
const salinityCases = [
  [34.5487, 34.711611927085727],
  [34.7275, 34.891255045714303],
  [34.8605, 35.024882197714305],
  [34.6810, 34.844535778285724],
  [34.5680, 34.731002934857159],
  [34.5600, 34.722965211428587]
];
for (const [sp, sr] of salinityCases) {
  near('published', density(sp, 20).referenceSalinityGPerKg, sr, 2e-13, `GSW SR, SP=${sp}`);
}

// IAPWS SR7-09 Table 6, p.9: pure-water density and dg/dP.
// https://iapws.org/technical-guidance/release/OceanLiquid.download
// p is ABSOLUTE Pa in the table: 1e8 Pa corresponds to 9989.8675 sea dbar.
// Tolerances cover half a unit in the last printed digit, with a small margin.
const waterCases = [
  [0, 0, 999.843071, 6e-7, 0.00100015695, 5.1e-12],
  [0, 9989.8675, 1045.27793, 6e-6, 0.000956683354, 5.1e-13],
  [40, 0, 992.216354, 6e-7, 0.00100784471, 5.1e-12]
];
for (const [t, p, rho, rhoTolerance, v, vTolerance] of waterCases) {
  const result = density(0, t, p);
  near('published', result.rho, rho, rhoTolerance, `SR7-09 water rho, t=${t}, p=${p}`);
  near('published', result.pureWaterSpecificVolumeM3PerKg, v, vTolerance,
    `SR7-09 water dg/dP, t=${t}, p=${p}`);
}

// IAPWS R13-08 Table 8(a,c), pp.17,19; SA=35.16504 g/kg => SP=35.
// https://www.teos-10.org/pubs/IAPWS-08.pdf
// The saline dg/dP is directly comparable (tolerance 6e-14 m3/kg).
// Table 8 uses full IAPWS-95 for water, whereas the module uses IAPWS-09.
// Therefore the combined density/volume tolerances (5e-5 kg/m3, 3e-11 m3/kg)
// cover that documented difference as well as rounding; they are not loosened
// numerical tolerances for the GSW checks above, which use the same water EOS.
const seawaterCases = [
  [0, 1028.10720, -0.0000274957224, 0.000972661217],
  [9989.8675, 1070.92645, -0.0000229123842, 0.000933770945]
];
for (const [p, rho, salineV, totalV] of seawaterCases) {
  const result = density(35, 0, p);
  near('published', result.rho, rho, 5e-5, `R13-08 seawater rho, p=${p}`);
  near('published', result.salineSpecificVolumeM3PerKg, salineV, 6e-14,
    `R13-08 saline dg/dP, p=${p}`);
  near('published', result.specificVolumeM3PerKg, totalV, 3e-11,
    `R13-08 total dg/dP, p=${p}`);
}

// Independent practical approximations requested for marine teaching:
// pure water at 4 C ~= 999.97 kg/m3 (0.01 kg/m3 tolerance); the conventional
// FWA/DWA freshwater 1.000 t/m3 is within 0.00005 t/m3 at that state.
// SP=35, t=20 C, surface seawater is within 0.00025 t/m3 of the conventional
// 1.025 t/m3. These constants are conventions, not temperature-independent EOS
// identities. Never calibrate the equation to force exactly 1000/1025 kg/m3.
near('practical', density(0, 4).rho, 999.97, 0.01, 'Fresh water at 4 C');
near('practical', density(0, 4).rhoTPerM3, 1.000, 0.00005, 'FWA freshwater convention');
near('practical', density(35, 20).rhoTPerM3, 1.025, 0.00025, 'FWA seawater convention at 20 C');

// Hand-calculated working values: SP=10 => SR=10.047154285714286 g/kg,
// x=sqrt(10/40)=0.5; t=20 => y=0.5; p=1000 => z=0.1;
// P=101325+1000*10000=10101325 Pa. SP=35 => SR=35.16504 g/kg.
const worked = density(10, 20, 1000);
near('working', worked.referenceSalinityGPerKg, 10.047154285714286, 2e-14, 'Hand SR');
near('working', worked.assumedAbsoluteSalinityGPerKg, 10.047154285714286, 2e-14, 'Hand assumed SA');
near('working', worked.salinityRoot, 0.5, 2e-16, 'Hand x');
near('working', worked.temperatureRatio, 0.5, 0, 'Hand y');
near('working', worked.pressureRatio, 0.1, 0, 'Hand z');
near('working', worked.absolutePressurePa, 10101325, 0, 'Hand absolute pressure');
near('working', density(35, 0).referenceSalinityGPerKg, 35.16504, 1e-14, 'Normal reference salinity');
near('working', density(0, 40).rhoTPerM3, 0.992216354, 6e-10, 'Published rho in t/m3');

// All dimensions refuse non-finite and unparsed/non-number inputs. No coercion
// of blank, comma string, null, booleans or boxed numbers into valid results.
const badValues = [NaN, Infinity, -Infinity, '', ' ', '8,5', '8.5', null,
  true, false, [], {}, new Number(35), 35n, Symbol('salinity')];
for (const value of badValues) {
  refuses([value, 20, 0], 'E_SP_NOT_FINITE', 'sp');
  refuses([35, value, 0], 'E_TEMPERATURE_NOT_FINITE', 'tC');
  refuses([35, 20, value], 'E_PRESSURE_NOT_FINITE', 'pDbar');
}
refuses([], 'E_SP_NOT_FINITE', 'sp');
refuses([35], 'E_TEMPERATURE_NOT_FINITE', 'tC');
refuses([undefined, 20], 'E_SP_NOT_FINITE', 'sp');
refuses([35, undefined], 'E_TEMPERATURE_NOT_FINITE', 'tC');
refuses([-Number.EPSILON, 20, 0], 'E_SP_RANGE', 'sp');
refuses([40.00000001, 20, 0], 'E_SP_RANGE', 'sp');
refuses([35, -Number.EPSILON, 0], 'E_TEMPERATURE_RANGE', 'tC');
refuses([35, 40.00000001, 0], 'E_TEMPERATURE_RANGE', 'tC');
refuses([35, 20, -Number.EPSILON], 'E_PRESSURE_RANGE', 'pDbar');
refuses([35, 20, 9989.86750001], 'E_PRESSURE_RANGE', 'pDbar');

// Monotonic checks are physical sanity checks, not independent numeric oracles.
// Reference-composition liquid water becomes denser with salinity over this
// grid. At SP=35 it becomes less dense with temperature above 4 C. Pressure
// raises density, including near freshwater's density maximum.
for (const t of [0, 4, 20, 40]) {
  for (const p of [0, 1000, 9989.8675]) {
    let previous = density(0, t, p).rho;
    for (const sp of [0.1, 1, 5, 10, 20, 35, 40]) {
      const next = density(sp, t, p).rho;
      check('monotonic', next > previous, `Salinity increases rho, SP=${sp}, t=${t}, p=${p}`);
      previous = next;
    }
  }
}
for (const p of [0, 1000, 9989.8675]) {
  let previous = density(35, 4, p).rho;
  for (const t of [5, 10, 20, 30, 40]) {
    const next = density(35, t, p).rho;
    check('monotonic', next < previous, `Temperature decreases rho, SP=35, t=${t}, p=${p}`);
    previous = next;
  }
}
for (const sp of [0, 5, 35, 40]) {
  for (const t of [0, 4, 20, 40]) {
    let previous = density(sp, t, 0).rho;
    for (const p of [10, 1000, 5000, 9989.8675]) {
      const next = density(sp, t, p).rho;
      check('monotonic', next > previous, `Pressure increases rho, SP=${sp}, t=${t}, p=${p}`);
      previous = next;
    }
  }
}

// Inclusive endpoints, immutable public metadata/results, and both classic
// browser-script and worker/Node global attachment. No DOM is supplied.
for (const sp of [0, 40]) for (const t of [0, 40]) for (const p of [0, 9989.8675]) {
  const result = density(sp, t, p);
  check('contract', result.valid === true && Number.isFinite(result.rho) && result.rho > 0,
    `Inclusive corner ${sp}/${t}/${p}`);
}
check('contract', Object.isFrozen(context.window.MT_SEAWATER), 'API frozen');
check('contract', Object.isFrozen(validRange) && Object.values(validRange).every(Object.isFrozen), 'Ranges deeply frozen');
check('contract', Object.isFrozen(worked), 'Result frozen');
check('contract', worked.model === 'TEOS-10-SA=SR-GIBBS' && worked.assumedAbsoluteSalinityAnomalyGPerKg === 0,
  'Model and explicit composition assumption');
check('contract', density(0, 20).salineSpecificVolumeM3PerKg === 0, 'Zero salinity has no saline contribution');
check('contract', density(35, 20).rho === density(35, 20, 0).rho && density(35, 20, undefined).rho === density(35, 20, 0).rho,
  'Default pressure is zero');
check('contract', density(35, 20).pDbar === 0 && density(35, 20).absolutePressurePa === 101325,
  'Zero sea pressure is one standard atmosphere absolute');
check('contract', density(35, 20, 9989.8675).absolutePressurePa === 100000000,
  'Upper pressure is exactly 100 MPa absolute');
check('contract', density(35, 20, 10).rho !== density(35, 20, 0).rho, 'Sea pressure is used, not discarded');
const workerContext = vm.createContext({});
vm.runInContext(source, workerContext);
check('contract', workerContext.MT_SEAWATER.density(35, 20).rho === density(35, 20).rho,
  'globalThis fallback agrees with browser attachment');

const checks = Object.values(counts).reduce((sum, value) => sum + value, 0);
console.log(`PASS seawater density: ${checks} checks ${JSON.stringify(counts)}`);
console.log(`Published GSW density cases: ${gswDensityCases.length}; max absolute difference ${maxGswError} kg/m3`);
